package com.taller.portal.dto;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.LocalDate;
/** Contratos HTTP para registro de clientes. */ public final class ClienteDtos { private ClienteDtos(){} /** Datos recibidos en la parte JSON multipart; tallerId es obligatorio para administrador y derivado para recepción. */ public record Registro(@NotBlank @Size(max=120) String nombreCompleto,@NotBlank @Size(max=120) String contactoAlternativo,@NotNull @Min(0) @Max(130) Integer edad,@NotNull @Past LocalDate fechaNacimiento,@NotBlank @Pattern(regexp="^[0-9+ ()-]{8,25}$") String telefonoPersonal,@NotBlank @Pattern(regexp="^[0-9+ ()-]{8,25}$") String telefonoTrabajo,@NotBlank @Email @Size(max=140) String email,@Email @Size(max=140) String emailTrabajo,@NotNull @Valid Direccion direccion,Long tallerId){} /** Dirección postal obligatoria. */ public record Direccion(@NotBlank @Size(max=120) String calle,@NotBlank @Size(max=100) String colonia,@NotBlank @Size(max=100) String municipio,@NotBlank @Size(max=100) String estado,@NotBlank @Pattern(regexp="^[0-9]{5}$") String codigoPostal){} /** Resultado serializable del registro. */ public record Respuesta(Long id,String mensaje){} }
